// =============================================================
// LÓGICA INTELIGENTE — Volte a Sorrir v1.7
// Sugestões com gap mínimo de 3h entre horários
// =============================================================

// ── 1. CONFIGURAÇÃO ───────────────────────────────────────────
const cfgNode = $('Configuracao Unidades').first().json;
const ca = cfgNode.config_agenda || {};

const TIMEZONE    = ca.timezone || 'America/Sao_Paulo';
const DUR_MIN     = ca.duracao_servico || 30;
const LIMITE_DIAS = ca.limite_dias_busca_normal || 7;
const GAP_MIN     = 180; // 3 horas em minutos

const PROF_ID       = String(ca.profissional?.id || '');
const PROF_NOME     = ca.profissional?.nome || 'Profissional';
const FALLBACK_ID   = String(ca.profissional_fallback?.id || '');
const FALLBACK_NOME = ca.profissional_fallback?.nome || '';

// ── 2. INPUT ──────────────────────────────────────────────────
const diasAPI = $input.all().map(i => i.json);

// ── 3. DADOS DO PEDIDO ────────────────────────────────────────
const insistiu = cfgNode.insistiu === true;
const hRaw     = cfgNode.horario_agendado || '';
const dRaw     = cfgNode.data_agendada || '';
const agora    = DateTime.now().setZone(TIMEZONE);

const hPreferidoRaw = cfgNode.horario_preferido;
const hPreferido = (hPreferidoRaw && hPreferidoRaw !== 'null' && hPreferidoRaw !== 'undefined')
  ? hPreferidoRaw : null;

let dtSolicitado = null;
if (dRaw && hRaw) {
  dtSolicitado = DateTime.fromFormat(`${dRaw} ${hRaw}`, 'yyyy-MM-dd HH:mm', { zone: TIMEZONE });
}

let diffDias = 0, bloqueado = false;
if (dtSolicitado?.isValid) {
  diffDias = dtSolicitado.startOf('day').diff(agora.startOf('day'), 'days').days;
  if (diffDias > LIMITE_DIAS && !insistiu) bloqueado = true;
}

// ── 4. HELPERS ────────────────────────────────────────────────
function horaParaMin(str) {
  if (!str) return -1;
  const p = str.split(':');
  return parseInt(p[0]) * 60 + parseInt(p[1] || '0');
}

// Converte bloco em minutos absolutos (data + hora) para comparação de gap
function blocoParaAbsMin(b) {
  const [yyyy, mm, dd] = b.data.split('-');
  const diasMs = new Date(parseInt(yyyy), parseInt(mm) - 1, parseInt(dd)).getTime();
  return Math.floor(diasMs / 60000) + b.minutos;
}

// Sugestões com gap mínimo — percorre blocos em ordem cronológica
function sugerirComGap(blocos, n = 3, gapMin = GAP_MIN) {
  const resultado = [];
  let ultimoAbsMin = -Infinity;

  for (const b of blocos) {
    const absMin = blocoParaAbsMin(b);
    if (absMin - ultimoAbsMin >= gapMin) {
      resultado.push(b);
      ultimoAbsMin = absMin;
      if (resultado.length >= n) break;
    }
  }
  return resultado;
}

// Sugestões com gap a partir de uma âncora (horário de referência no mesmo dia)
// Ordena por proximidade à âncora, depois aplica gap
function sugerirComGapAncorado(blocos, minAncora, n = 3, gapMin = GAP_MIN) {
  // Ordena por distância ao horário solicitado
  const ordenados = [...blocos].sort((a, b) =>
    Math.abs(a.minutos - minAncora) - Math.abs(b.minutos - minAncora)
  );

  const resultado = [];
  let ultimoAbsMin = -Infinity;

  for (const b of ordenados) {
    const absMin = blocoParaAbsMin(b);
    // Verifica gap em relação a todos os já selecionados
    const respeitaGap = resultado.every(r =>
      Math.abs(blocoParaAbsMin(r) - absMin) >= gapMin
    );
    if (respeitaGap) {
      resultado.push(b);
      if (resultado.length >= n) break;
    }
  }

  // Retorna ordenado cronologicamente para exibição
  return resultado.sort((a, b) => a.minutos - b.minutos);
}

// Sugestões por horário preferido — cronológico por dia, slot mais próximo do preferido
function sugerirPorPreferido(blocos, hPref, n = 3) {
  const minPref = horaParaMin(hPref);
  const porDia = {};
  for (const b of blocos) {
    if (!porDia[b.data]) {
      porDia[b.data] = b;
    } else {
      const diffAtual = Math.abs(porDia[b.data].minutos - minPref);
      const diffNovo  = Math.abs(b.minutos - minPref);
      if (diffNovo < diffAtual) porDia[b.data] = b;
    }
  }
  return Object.keys(porDia).sort().slice(0, n).map(d => porDia[d]);
}

// ── 5. PROCESSAR UM DIA ───────────────────────────────────────
function processarDia(dia) {
  const slots = (dia.AvaliableTimes || []).filter(s => s.isSelectable !== false);

  const blocosPrimario = [];
  const blocosFallback = [];

  for (const slot of slots) {
    const profIdStr = String(slot.professionalId);
    if (profIdStr === PROF_ID) {
      blocosPrimario.push({
        data:        dia.jsonDate,
        semana:      dia.Week,
        minutos:     horaParaMin(slot.from),
        horario:     slot.from,
        horario_fim: slot.to,
        profId:      PROF_ID,
        profNome:    PROF_NOME
      });
    } else if (FALLBACK_ID && profIdStr === FALLBACK_ID) {
      blocosFallback.push({
        data:        dia.jsonDate,
        semana:      dia.Week,
        minutos:     horaParaMin(slot.from),
        horario:     slot.from,
        horario_fim: slot.to,
        profId:      FALLBACK_ID,
        profNome:    FALLBACK_NOME
      });
    }
  }

  const blocos = blocosPrimario.length > 0 ? blocosPrimario : blocosFallback;
  return blocos.sort((a, b) => a.minutos - b.minutos);
}

// ── 6. TODOS OS BLOCOS ────────────────────────────────────────
let todosBlocos = [];
for (const dia of diasAPI) todosBlocos = todosBlocos.concat(processarDia(dia));

// ── 7. FORMATAÇÃO ─────────────────────────────────────────────
const fmtBloco = b => {
  const [yyyy, mm, dd] = b.data.split('-');
  return `🗓️ *${dd}/${mm} (${b.semana})* às *${b.horario}* – *${b.horario_fim}* com ${b.profNome}`;
};

const dtLabel = dtSolicitado?.isValid
  ? dtSolicitado.setLocale('pt-BR').toFormat('dd/MM (cccc)')
  : (dRaw || 'data solicitada');

const prefLabel = hPreferido
  ? `\n\n💡 _Priorizei horários próximos à sua preferência: *${hPreferido}*_`
  : '';

// ── 8. DECISÃO PRINCIPAL ──────────────────────────────────────
let resultado, exactMatch = false;
const sugestoesHorarios = [];

// CAMINHO A — Data distante + NÃO insistiu
if (bloqueado) {
  const proximos = hPreferido
    ? sugerirPorPreferido(todosBlocos, hPreferido, 3)
    : sugerirComGap(todosBlocos, 3);
  if (proximos.length === 0) {
    resultado = `😕 Não há horários disponíveis no momento. Posso verificar outra data?`;
  } else {
    proximos.forEach(b => sugestoesHorarios.push(`${b.data} ${b.horario}`));
    resultado =
      `⚠️ A data que você pediu (*${dtLabel}*) está a *${Math.ceil(diffDias)} dias* de hoje.\n\n` +
      `Para garantir um atendimento mais rápido, separei os primeiros horários disponíveis:${prefLabel}\n\n` +
      proximos.map(fmtBloco).join('\n');
  }
}
// CAMINHO B — Data distante + insistiu
else if (diffDias > LIMITE_DIAS && insistiu) {
  const dataAlvo      = dtSolicitado.toFormat('yyyy-MM-dd');
  const minSolicitado = (hRaw && hRaw !== '00:00') ? horaParaMin(hRaw) : -1;
  const blocosDoDia   = todosBlocos.filter(b => b.data === dataAlvo);
  const blocoExato    = minSolicitado >= 0 ? blocosDoDia.find(b => b.minutos === minSolicitado) : null;

  if (blocoExato) {
    exactMatch = true;
    sugestoesHorarios.push(`${blocoExato.data} ${blocoExato.horario}`);
    resultado = `✅ Consegui o horário que você pediu!\n\n${fmtBloco(blocoExato)}\n\nConfirmo o agendamento?`;
  } else if (blocosDoDia.length === 0) {
    const proximos = hPreferido
      ? sugerirPorPreferido(todosBlocos, hPreferido, 3)
      : sugerirComGap(todosBlocos, 3);
    proximos.forEach(b => sugestoesHorarios.push(`${b.data} ${b.horario}`));
    resultado =
      `😕 Não há horários disponíveis em *${dtLabel}*.\n\nSeparei os primeiros horários disponíveis:${prefLabel}\n\n` +
      proximos.map(fmtBloco).join('\n') + `\n\nQual prefere? Ou verifico outro dia?`;
  } else {
    // Tem slots no dia — sugere ancorado no horário solicitado com gap
    const opcoes = minSolicitado >= 0
      ? sugerirComGapAncorado(blocosDoDia, minSolicitado, 3)
      : sugerirComGap(blocosDoDia, 3);
    opcoes.forEach(b => sugestoesHorarios.push(`${b.data} ${b.horario}`));
    resultado =
      `O horário das *${hRaw}* não está disponível em *${dtLabel}*, mas encontrei estas opções neste mesmo dia:${prefLabel}\n\n` +
      opcoes.map(fmtBloco).join('\n') + `\n\nQual prefere? Ou verifico outro dia?`;
  }
}
// CAMINHOS C / D — Data normal (≤ 7 dias)
else {
  const dataAlvo      = dtSolicitado?.isValid ? dtSolicitado.toFormat('yyyy-MM-dd') : null;
  const minSolicitado = (hRaw && hRaw !== '00:00') ? horaParaMin(hRaw) : -1;
  const blocosDoDia   = dataAlvo ? todosBlocos.filter(b => b.data === dataAlvo) : todosBlocos;
  const blocoExato    = (minSolicitado >= 0 && blocosDoDia.length > 0)
    ? blocosDoDia.find(b => b.minutos === minSolicitado) : null;

  if (blocoExato) {
    exactMatch = true;
    sugestoesHorarios.push(`${blocoExato.data} ${blocoExato.horario}`);
    resultado =
      `✅ Ótima notícia! O horário *${dtLabel} às ${blocoExato.horario}* está disponível ` +
      `com *${blocoExato.profNome}*.\n\nPosso confirmar sua avaliação?`;
  } else if (blocosDoDia.length === 0) {
    // Sem slots no dia — busca em todos com gap
    const proximos = hPreferido
      ? sugerirPorPreferido(todosBlocos, hPreferido, 3)
      : sugerirComGap(todosBlocos, 3);
    if (proximos.length === 0) {
      resultado = `😕 Não há horários disponíveis no período consultado. Posso verificar outras datas?`;
    } else {
      proximos.forEach(b => sugestoesHorarios.push(`${b.data} ${b.horario}`));
      resultado =
        `😕 Não há horários disponíveis em *${dtLabel}*.\n\nSeparei os primeiros horários disponíveis:${prefLabel}\n\n` +
        proximos.map(fmtBloco).join('\n') + `\n\nQual desses fica melhor para você?`;
    }
  } else {
    // Tem slots no dia mas não o horário exato — ancorado no solicitado com gap
    const opcoes = minSolicitado >= 0
      ? sugerirComGapAncorado(blocosDoDia, minSolicitado, 3)
      : sugerirComGap(blocosDoDia, 3);
    opcoes.forEach(b => sugestoesHorarios.push(`${b.data} ${b.horario}`));
    const intro = minSolicitado >= 0
      ? `O horário das *${hRaw}* não está disponível para *${dtLabel}*, mas encontrei estas opções:`
      : `Encontrei os seguintes horários disponíveis para *${dtLabel}*:`;
    resultado = `📅 ${intro}${prefLabel}\n\n` + opcoes.map(fmtBloco).join('\n') + `\n\nQual desses fica melhor para você?`;
  }
}

// ── 9. OUTPUT ─────────────────────────────────────────────────
return {
  json: {
    resultado,
    sugestoes_horarios:      sugestoesHorarios,
    data_distante_bloqueada: bloqueado,
    exact_match:             exactMatch,
    diff_dias:               Math.ceil(diffDias),
    total_dias_api:          diasAPI.length,
    total_blocos_validos:    todosBlocos.length
  }
};

